// LabFlow schedule page: show the day's bookings sorted by start time.
export type Entry = { id: number; start: number };

export function sortByStart(list: Entry[]): Entry[] {
  return list.sort((a, b) => a.start - b.start);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { sortByStart } from '../src/sort.ts';

const day = () => [{ id: 1, start: 780 }, { id: 2, start: 480 }, { id: 3, start: 600 }];

test('returns the bookings ordered by start', () => {
  assert.deepEqual(sortByStart(day()).map((e) => e.id), [2, 3, 1]);
});
test('leaves the caller\'s list in booking order (id 1, 2, 3)', () => {
  const mine = day();
  sortByStart(mine);
  assert.deepEqual(mine.map((e) => e.id), [1, 2, 3]);
});

// Correct callers: a page that only has a READ-ONLY view of the schedule must be able to call sortByStart.
import { sortByStart, type Entry } from '../src/sort.ts';

const shared: readonly Entry[] = [{ id: 1, start: 780 }, { id: 2, start: 480 }];
const timeline: Entry[] = sortByStart(shared);
console.log(timeline.length);

