// Turn '08:00-10:00' into [480, 600] — minutes since 00:00, start then end.
export type TimeRange = number[];

function minutes(hhmm: string): number {
  const [h, m] = hhmm.split(':');
  return Number(h) * 60 + Number(m);
}

export function toRange(text: string): TimeRange {
  const [from = '', to = ''] = text.split('-');
  return [minutes(from), minutes(to)];
}

export function minutesOf(r: TimeRange): number {
  const [start = 0, end = 0] = r;
  return end - start;
}

import { toRange, minutesOf, type TimeRange } from '../src/range.ts';

const three: TimeRange = [480, 600, 660]; // expect TS2322
toRange('08:00-10:00')[2]; // expect TS2493
minutesOf([600]); // expect TS2345
const start: number = toRange('08:00-10:00')[0];
console.log(three, start);

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toRange, minutesOf } from '../src/range.ts';

test("'08:00-10:00' becomes [480, 600]", () => assert.deepEqual(toRange('08:00-10:00'), [480, 600]));
test('a two-hour range lasts 120 minutes', () => assert.equal(minutesOf(toRange('08:00-10:00')), 120));

