// Turn '08:00-10:00' into [480, 600] — minutes since 00:00, start then end.
// A tuple: exactly two numbers, and each position has a meaning (labels show up in the editor).
export type TimeRange = readonly [start: number, end: number];

function minutes(hhmm: string): number {
  const [h, m] = hhmm.split(':');
  return Number(h) * 60 + Number(m);
}

export function toRange(text: string): TimeRange {
  const [from = '', to = ''] = text.split('-');
  return [minutes(from), minutes(to)];
}

export function minutesOf(r: TimeRange): number {
  return r[1] - r[0];     // a tuple knows positions 0 and 1 exist: no undefined here
}

