// Move a booking later or earlier by some minutes (e.g. the lab opens 30 minutes late).
export type TimeRange = [start: number, end: number];

export function shift(r: TimeRange, by: number): TimeRange {
  r[0] += by;
  r[1] += by;
  return r;
}

import { shift, type TimeRange } from '../src/range.ts';

const r: TimeRange = [480, 600];
r.push(660); // expect TS2339
r[0] = 0; // expect TS2540
const later: TimeRange = shift(r, 30);
console.log(later);

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { shift } from '../src/range.ts';

test('08:00-10:00 shifted by 30 is 08:30-10:30', () => assert.deepEqual(shift([480, 600], 30), [510, 630]));
test('the original range is unchanged', () => {
  const r: [number, number] = [480, 600];
  shift(r, 30);
  assert.deepEqual(r, [480, 600]);
});

