// Which parts of the opening day (07:00-21:00) are still free?
// booked: ranges [start, end] in minutes, in ANY order, never overlapping.
export const OPEN = 420;
export const CLOSE = 1260;

export function freeGaps(booked) {
  return [];
}

import { freeGaps } from '../src/gaps.ts';

freeGaps([[480, 600, 700]]); // expect TS2322
freeGaps(['08:00-10:00']); // expect TS2322
const shared = [[480, 600]] as const;
console.log(freeGaps(shared).length);

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { freeGaps } from '../src/gaps.ts';

test('three bookings leave three gaps', () => {
  assert.deepEqual(freeGaps([[780, 900], [480, 600], [600, 720]]), [[420, 480], [720, 780], [900, 1260]]);
});
test('an empty day is one big gap', () => assert.deepEqual(freeGaps([]), [[420, 1260]]));
test('a booking until closing time leaves no gap at the end', () => assert.deepEqual(freeGaps([[420, 1260]]), []));
test("the caller's list is not reordered", () => {
  const mine: [number, number][] = [[780, 900], [480, 600]];
  freeGaps(mine);
  assert.deepEqual(mine, [[780, 900], [480, 600]]);
});

